    [2379] = "어둠의 틈에 있는 잔도잔과 대화하십시오.",
    [2380] = "오그리마의 어둠의 틈에 있는 셴툴과 대화하십시오.",
    [2381] = "톱니항에 있는 비운의 레닉스에게 남쪽바다해적단 보물을 가져가야 합니다. 레닉스의 기계장치에서 E.C.A.C.와 도둑 도구를 얻는 것도 잊지 마십시오. 임무를 완수하려면 이 두 가지가 모두 필요합니다. 유별나게 공격적인 앵무새에게 맞서게 되면 E.C.A.C.를 사용하십시오!",
    [2382] = "톱니항으로 가서 비운의 레닉스와 대화하십시오.",
    [2383] = "간결한 양피지를 읽어보고 프랑에게 양피지를 가져가야 합니다.",
