    [2418] = "황야의 땅에 있는 리글퍼즈에게 덴트리움 마법석 8개와 안알레움 마법석 8개를 가져가야 합니다.",
    [2438] = "돌라나르에 있는 탈론카이 스위프트루트에게 에메랄드의 꿈 흡입기를 가져다주어야 합니다.",
    [2439] = "아이언포지 은행에 있는 디니타 스톤맨틀에게 사례 보증 서류를 가져가야 합니다.",
    [2440] = "썬더 블러프에 있는 베나 윈터후프에게 사례 보증 서류를 가져가야 합니다.",
    [2458] = "진흙 늪 북쪽에 있는 투자개발회사 탑으로 가서 검은손 도적단의 비밀 요원인 감독관 피줄과 접촉해야 합니다. 탑이 보이면 섬광탄포를 사용해 감독관 피줄에게 당신이 도착했음을 알리십시오. 섬광탄은 2번 발사해야 하며, 그 후 감독관 피줄에게 다가가 검은손 도적단 /경례를 해야 합니다. 피줄은 자기가 모르는 자는 무조건 처치하려 들기 때문에 정확한 순서대로 수행해야 합니다.",
    [2459] = "돌라나르에 있는 탈론카이 스위프트루트가 나무옹이일족 비술사 7명을 처치하고 잃어버린 보석을 찾아달라고 부탁했습니다.",
    [2460] = "셴툴에게 검은손 도적단 /경례를 해 보이십시오.",
    [2478] = "현장감독 실릭시즈에게서 실릭시즈의 탑 열쇠를 훔쳐낸 다음, 돌연변이 투자개발회사 일꾼 2명과 투자개발회사 순찰대원 2명, 그리고 투자개발회사 망꾼 2명을 처치해야 합니다. 총감독 갤리윅스를 암살하고 그의 머리카락을 손에 넣은 후, 갤리윅스의 금고를 열고 잔질의 변화된 혼합물을 훔쳐내야 합니다. 그 혼합물과 갤리윅스의 머리카락을 오그리마에 있는 셴툴에게 가져다주고 다음 지시를 받으십시오.",
    [2479] = "힐스브래드 구릉지의 타렌 밀농장으로 가서 서지 히노트에게 잔질의 혼합물 견본을 전해야 합니다. 타렌 밀농장으로 가려면 먼저 비행선을 타고 언더시티로 가야 합니다. 도착하면 남쪽 길을 따라 은빛소나무 숲을 지나 힐스브래드 쪽으로 가야 합니다. 표지판을 따라 가십시오!",
