    [3962] = "마샬의 야영지 남쪽에 있는 불기둥 마루로 가야 합니다. 불바람을 찾아 토템을 이용해 오라를 제거하십시오. 정령을 물리친 후, 동굴에서 황금 불길을 손에 넣어야 합니다.",
    [3981] = "검은바위 나락에서 사령관 고르샤크를 찾아야 합니다. 조잡하게 그려진 오크 그림에 쇠창살이 그려져 있던 것이 생각납니다. 감옥 같은 곳을 찾아봐야 할 것 같습니다.",
    [3982] = "고르샤크를 보호해야 합니다.",
    [4001] = "카란 마이트해머와 대화하여 공주 모이라 브론즈비어드의 납치에 대한 정보를 모은 후, 그 정보를 오그리마에 있는 스랄에게 가져가야 합니다. 고르샤크가 카란이 근처 감방에 갇혀 있다고 말했던 것이 기억납니다.",
    [4002] = "스랄이 계획한 임무를 맡을 준비가 되었으면 스랄과 다시 한번 대화하십시오.",
    [4003] = "제왕 다그란 타우릿산을 처치하고 그의 사악한 마법에서 공주 모이라 브론즈비어드를 해방시켜야 합니다.",
    [4004] = "스랄에게 돌아가야 합니다!",
    [4005] = "아쿠오르의 책, 은백색 발톱, 그리고 강철나무 심장을 가지고 타나리스로 가십시오. 아쿠오르의 책을 사용해 아쿠에멘타스를 소환해야 합니다. 토템을 완성하면 마샬의 야영지에 있는 J.D. 콜리에게 가져가야 합니다.",
    [4021] = "크로스로드 서쪽에 있는 렉타르 데스게이트에게 크롬자르의 깃발 조각을 가져가야 합니다.",
    [4022] = "벨라로크 윈드블레이드에게서 받은 검은용군단 허물을 키루스 테레펜터스에게 보여줘야 합니다.",
    [4023] = "키루스 테레펜터스에게 자신의 가치를 증명해 보여야 합니다. 키루스가 이미 당신이 가치가 없다는 사실을 알고 있는 것 같은 느낌이 듭니다.",
    [4024] = "검은바위 나락으로 가서 밸가르를 처치하십시오. 이 거인이 검은바위 나락 내에 살고 있다는 것만 알고 있으며 밸가르의 시체에 변형된 검은용군단 허물을 사용해 불의 정수를 추출해야만 합니다. 키루스 테레펜터스에게 담겨진 불의 정수를 가져가야 합니다.",
    [4061] = "불타는 평원으로 가서 제사장 테오도라 뮬바다니아에게 가져갈 부서진 원소 파편 10개를 모아야 합니다. 그 지역의 골렘과 정령들에게서 이 파편을 구할 수 있을 거라고 테오도라가 말했던 것이 기억납니다.",
    [4062] = "로트윌 베리아투스에게 원소 파편 견본을 가져가야 합니다. 테오도라가 로트윌은 동쪽 야영지에 있다고 얘기했던 것이 기억납니다.",
    [4063] = "골렘 군주 아젤마크를 찾아 처치하고 그 증거로 그의 머리카락을 로트윌에게 가져가야 합니다. 그리고 아젤마크를 호위하는 재앙의 피조물과 맹위의 전투골렘들에게서 온전한 원소핵 10개도 모아야 합니다.",
    [4081] = "검은바위 나락으로 가서 사악한 침략자들을 쳐부수십시오! 장군 고어투스가 성난모루단 보초 15명, 성난모루단 교도관 10명, 성난모루단 보병 5명을 처치해 달라고 부탁했습니다. 임무를 완수하면 장군 고어투스에게 돌아가십시오.",
    [4082] = "검은바위 나락으로 가서 사악한 침략자들을 쳐부수십시오! 장군 고어투스가 성난모루단 간호병 10명, 성난모루단 병사 10명, 그리고 성난모루단 장교 10명을 처치해 달라고 부탁했습니다. 임무를 완수하면 고어투스에게 돌아가십시오.",
    [4084] = "악령의 숲에 있는 에리단 블루윈드에게 은백색 발톱 11개와 강철나무 심장 1개를 가져가야 합니다.",
    [4101] = "악령의 숲에 있는 아라탄드리스 실버스카이에게 핏빛 호박석 15개를 가져가야 합니다.",
