    [4866] = "검은바위 첨탑 중심부에서 여왕 불그물거미를 찾을 수 있습니다. 여왕 불그물거미를 공격하거나 접근하여 그 독에 중독되어야 합니다. 독에 걸릴 확률을 높이기 위해서는 거미를 죽여야 할 수도 있습니다. 중독되면 털보 존에게 돌아가서 그가 그 독을 추출하게 해야 합니다.",
    [4867] = "와로쉬의 두루마리를 읽어야 합니다. 와로쉬에게 그의 부적을 가져가야 합니다.",
    [4881] = "백사장 야영지에 있는 카나티 그레이클라우드에게 가서 암살 음모에 대해 경고해 주어야 합니다.",
    [4882] = "피멍울 초소에 있는 트룰 페일베인에게 푸른 깃털달린 목걸이를 갖다주어야 합니다.",
    [4883] = "푸른 깃털달린 목걸이를 나라 와일드메인에게 갖다주어야 합니다.",
    [4901] = "엘룬의 제단을 여는 과정에서 란샬라를 보호해야 합니다. 성공하면 루테란 마을에 있는 에렐라스 앰버스카이에게 발견한 내용을 보고해야 합니다.",
    [4902] = "다르나서스에 있는 대드루이드 판드랄 스테그헬름과 대화해야 합니다.",
    [4903] = "대군주 오모크와 대장군 부네, 대군주 웜타라크를 처단해야 합니다. 검은바위의 중요한 문서들을 확보해야 합니다. 임무를 완수하는 대로 카르가스의 장군 고어투스에게로 돌아가야 합니다.",
    [4904] = "라코타 윈드송을 먹구름 봉우리에서 구출한 후, 높새바람 봉우리에 있는 탈리아 앰버하이드와 대화하십시오.",
    [4906] = "에리단 블루윈드를 위해 비취불꽃 지옥소환사 8명과 배반자 8명, 그리고 요술사 8명과 사바릭을 처단해야 합니다. 임무가 완수되는 대로 에리단에게 돌아가십시오.",
    [4907] = "팅키 스팀보일과 대화해야 합니다.",
    [4921] = "크로스로드에 있는 만크릭을 위해 그의 아내의 흔적을 찾아 돌아가야 합니다.",
    [4941] = "오그리마의 스랄의 요새에 있는 아이트리그와 대화해야 합니다. 아이트리그의 얘기를 듣고 난 후에는 대족장 스랄과 상의해야 합니다.",
    [4961] = "보주의 악마를 물리치고 타베사와 대화하십시오.",
    [4962] = "지옥의 루비를 가지고 가서 잊혀진 땅에 서식하는 지옥사냥개 중 한 마리에게 사용해야 합니다. 성공하면 지옥의 루비와 사로잡은 지옥사냥개의 영혼을 불모의 땅에 있는 미네라에게 가져가야 합니다.",
    [4963] = "지옥불 에메랄드를 가지고 가서 잊혀진 땅의 지옥불정령 중 하나에게 사용해 영혼을 사로 잡아야 합니다. 성공하면 지옥불 에메랄드와 사로잡은 지옥불정령의 영혼을 불모의 땅에 있는 미네라에게 가져가야 합니다.",
    [4964] = "미네라 보이드렌더가 다르오라힐의 보주를 완성시킬 때까지 기다렸다가 그녀에게 말을 걸어야 합니다.",
    [4965] = "불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.",
    [4966] = "켄타우로스의 공격으로부터 카나티 그레이클라우드를 보호해야 합니다.",
    [4967] = "불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.",
    [4968] = "불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.",
    [4969] = "불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.",
    [4970] = "톱니이빨곰 고기 5개와 서리바람 키메라 고기 5개를 여명의 설원에 있는 리베른 프로스트윈드에게 갖다주어야 합니다.",
    [4971] = "안돌할 저장고 근처에서 시간의 재배열기를 이용해 시간의 기생충들을 찾아내십시오. 시간의 기생충 15마리를 처치한 후, 서부 역병지대의 안돌할 여관에 있는 크로미에게 시간의 재배열기를 가져가야 합니다.",
    [4972] = "안돌할 도시의 폐허에서 안돌할 시계 5개를 찾아 서부 역병지대의 안돌할 여관에 있는 크로미에게 가져가야 합니다.",
    [4973] = "안돌할 도시의 폐허에서 안돌할 시계 5개를 찾아 서부 역병지대의 안돌할 여관에 있는 크로미에게 가져가야 합니다.",
    [4974] = "검은바위 첨탑으로 가서 대족장 렌드 블랙핸드를 처치하십시오. 그 증거로 그의 머리카락을 가지고 오그리마로 돌아와야 합니다.",
    [4975] = "미네라 보이드렌더가 노오라힐의 보주를 완성하길 기다렸다가 그녀에게 말을 걸어야 합니다.",
    [4976] = "정화된 지옥의 보주를 불모의 땅의 미네라에게 가져가야 합니다.",
    [4981] = "검은바위 첨탑으로 가서 비쥬에게 무슨 일이 생겼는지 알아봐야 합니다.",
    [4982] = "비쥬의 소지품을 찾아서 그녀에게 돌아가야 합니다. 비쥬가 도시의 바닥에 소지품을 숨겼다고 했습니다.",
    [4983] = "비쥬의 정찰 보고서를 가지고 카르가스의 렉스로트에게 가야 합니다.",
    [4984] = "역병에 걸린 늑대 8마리를 처치한 후, 서부 역병지대의 고통의 흉가에 있는 멀그리스 딥리버에게 돌아가야 합니다.",
    [4985] = "오염된 불곰 8마리를 처치한 후, 서부 역병지대의 고통의 흉가에 있는 멀그리스 딥리버에게 돌아가야 합니다.",
    [4986] = "문자가 새겨진 떡갈나무 가지에 걸린 문자로 미루어볼 때 타우렌 드루이드가 이 가지를 가져가려고 한 장소는 다르나서스에 있는 세나리온 의회입니다. 그곳에서 드루이드를 한 명 찾아 도움을 요청하십시오.",
    [4987] = "문자가 새겨진 떡갈나무 가지에 걸린 문자로 미루어볼 때 타우렌 드루이드가 이 가지를 가져가려고 한 장소는 썬더 블러프에 있는 세나리온 의회입니다. 그곳에서 드루이드를 한 명 찾아 도움을 받도록 하십시오.",
    [5001] = "비쥬의 소지품을 찾아 그녀에게 돌려줘야 합니다!",
    [5002] = "불타는 평원에 있는 치안대장 맥스웰에게 비쥬의 정보를 전해야 합니다.",
    [5021] = "유령 여인의 두서없는 말을 들으니 소포를 전달해야 했던 것 같습니다. 자신의 말이 있던 곳에 소포가 있다고 했는데, 말이 어디 있는지, 그리고 소포를 어디로 전달해야 하는지에 대해서는 이해할 수 없는 말만 늘어놓습니다.",
    [5022] = "스톰윈드의 왕실 조사원과 대화하여 엠마 펠스톤의 행방을 알아내십시오. 인구조사국 담당자는 보통 스톰윈드 시청에 있습니다.",
    [5023] = "언더시티의 왕실감독원과 대화하여 제레미어 펠스톤의 행방을 알아내십시오. 인구조사국 담당자는 보통 길드 사무소 근처에 있습니다.",
    [5041] = "크로스로드 보급품 상자를 찾아서 불모의 땅의 톨크에게 가져가 주어야 합니다.",
    [5047] = "눈망루 마을에 있는 말리퍼스 다크해머와 대화해야 합니다.",
    [5048] = "스톰윈드에서 올엠마를 찾아 그녀가 엠마 펠스톤인지 확인하십시오. 그녀가 정말 엠마 펠스톤이라면 재니스 펠스톤이 보낸 소포를 원할지도 모릅니다.",
    [5049] = "언더시티에서 제레미어 페이슨을 찾아 그가 정말로 제레미어 펠스톤인지 확인하십시오. 그가 정말로 제레미어 펠스톤이라면 재니스 펠스톤이 보낸 소포를 원할지도 모릅니다.",
    [5050] = "서부 역병지대에 있는 재니스 펠스톤에게 행운의 부적 조각을 되돌려줘야 합니다.",
    [5051] = "서부 역병지대에 있는 펠스톤 농장에서 행운의 부적 목줄을 찾아 붙이십시오. 서부 역병지대의 펠스톤 농장에 있는 재니스 펠스톤에게 행운의 부적을 가져가야 합니다.",
    [5052] = "불모의 땅의 타우라조 야영지에 있는 뻐드렁니에게 혈석을 가져가야 합니다. 아감마간의 힘을 빌린 축복을 받고 싶다면 최대한 많이 수집해야 합니다.",
    [5054] = "여명의 설원 눈망루 마을에 있는 스톰 섀도후프가 우르시우스를 처치해달라고 요청했습니다.",
    [5055] = "여명의 설원 눈망루 마을에 있는 스톰 섀도후프가 브룸랜을 처치해 달라고 요청했습니다.",
    [5056] = "여명의 설원 눈망루 마을에 있는 스톰 섀도후프가 샤이로탐을 처치해 달라고 요청했습니다.",
    [5057] = "썬더 블러프에 있는 멜로르 스톤후프에게 스톰 섀도후프의 문장을 가져가야 합니다.",
    [5061] = "다르나서스로 돌아가 마스렌길 베어워커에게 바다표범의 펜던트를 보여 <name>어야 합니다.",
    [5062] = "불꽃 용설란 10포기를 모아 썬더 블러프 장로의 봉우리에 있는 마가타 그림토템을 찾아가야 합니다.",
    [5063] = "붉은 학자의 모자를 얻으려면 말리퍼스 다크해머에게 다음 재료를 갖다주어야 합니다. 온전한 괴수의 가죽 1개, 닳아해진 누더기골렘 조각 5개, 신비한 수정 8개, 마력 깃든 붉은 실타래 5개 제작비로 50골드도 가져가야 합니다.",
    [5064] = "먹구름 봉우리에 있는 비밀 쪽지 3개를 찾아 와야 합니다.",
    [5065] = "세 번째와 네 번째 모쉬아루 서판을 찾아 타나리스에 있는 발굴조사단장 아이언부트에게 갖다주어야 합니다.",
    [5066] = "사령관 아쉬람 발러피스트를 찾아야 합니다. 그의 주둔지는 알터랙 산맥 북쪽의 서리바람 야영지입니다.",
    [5067] = "아카나의 다리보호구를 얻으려면 말리퍼스 다크해머에게 다음 재료를 갖다주어야 합니다. 온전한 괴수의 가죽 1개, 닳아해진 누더기골렘 조각 5개, 아케이나이트 주괴 5개, 프로스트위스퍼의 불변의 영액 5개. 제작비로 50골드도 가져가야 합니다.",
    [5068] = "핏빛갈증의 흉갑을 얻으려면 말리퍼스 다크해머에게 다음 재료를 갖다주어야 합니다. 온전한 괴수의 가죽 1개, 닳아해진 누더기골렘 조각 10개, 아케이나이트 주괴 5개, 어둠의 허물 5개. 그리고 제작 비용으로 50골드도 갖고 가야 합니다.",
