    [5093] = "고위집행관 델링턴을 찾아가야 합니다. 그의 주둔지는 티리스팔 숲과 언더시티의 동쪽에 있는 보루에 있습니다.",
    [5094] = "고위집행관 델링턴을 찾아가야 합니다. 그의 주둔지는 티리스팔 숲과 언더시티의 동쪽에 있는 보루에 있습니다.",
    [5095] = "고위집행관 델링턴을 찾아가야 합니다. 그의 주둔지는 티리스팔 숲과 언더시티의 동쪽에 있는 보루에 있습니다.",
    [5096] = "펠스톤 농장과 달슨의 눈물 사이에 있는 붉은십자군의 야영지로 가서 지휘 막사를 파괴하십시오. 기지에 스컬지 깃발을 세운 후, 서부 역병지대의 보루에 있는 고위집행관 델링턴에게 돌아가야 합니다.",
    [5097] = "신호 횃불로 안돌할의 각 탑을 표시해야 합니다. 성공적으로 표시하려면 탑의 입구에 서야 합니다. 네 개의 감시탑에 모두 표시했으면 신호 횃불을 서부 역병지대의 서리바람 야영지에 있는 사령관 아쉬람 발러피스트에게 가져가십시오.",
    [5098] = "신호 횃불로 안돌할의 각 탑을 표시해야 합니다. 성공적으로 표시하려면 탑의 입구에 서야 합니다. 네 개의 감시탑에 모두 표시했으면 신호 횃불을 서부 역병지대의 보루에 있는 고위집행관 델링턴에게 가져가십시오.",
    [5102] = "검은바위 첨탑으로 가서 사령관 드라키사스를 처치해야 합니다. 임무를 완수하면 치안대장 맥스웰에게 돌아가야 합니다.",
    [5103] = "아제로스 어딘가에 누군가가 이 건틀릿으로 뭘 해야 하는지 알고 있을 겁니다. 행운을 빕니다!",
    [5121] = "여명의 설원에 있는 도노바 스노우덴이 대부족장 눈사태를 처치해 달라고 부탁했습니다.",
    [5123] = "여명의 설원에 있는 도노바 스노우덴에게 휘갈겨 쓴 일지를 가져다주어야 합니다.",
    [5124] = "마력 깃든 토륨 주괴 6개, 불의 정수 2개, 별루비 4개를 말리퍼스 다크해머에게 갖다주어야 합니다. 불타지 않은 판금 건틀릿도 주어야 합니다.",
    [5126] = "로락스와 대화를 해서 그가 하는 이야기를 들어야 합니다.",
    [5127] = "검은바위 첨탑으로 가서 고랄루크 앤빌크랙을 찾아 처치한 후, 핏물이 깃든 창을 그의 심장에 꽂으십시오. 창이 그의 영혼을 흡수하면 영혼이 깃든 창으로 변합니다. 벼려지지 않은 룬문자 흉갑도 찾아야 합니다. 영혼이 깃든 창과 벼려지지 않은 룬문자 흉갑을 여명의 설원에 있는 로락스에게 갖다주십시오.",
    [5128] = "악령의 숲 남부에 있는 켈레크 스카이키퍼에게 휘갈겨 쓴 일지를 갖다주어야 합니다.",
    [5141] = "단단한 전갈 흉갑 2개와 단단한 전갈 장갑 2개, 닳아해진 용비늘 10개를 아즈샤라에 있는 피터 갈렌에게 가져가야 합니다. 이 임무를 완수하면 용비늘 가죽세공술을 배우지만... 원소 가죽세공술과 전통 가죽세공술은 영영 익힐 수 없게 됩니다. 그러므로 피터가 준 임무를 수행하기 전에 정말로 이 길을 가고 싶은지 확실히 결정하십시오.",
    [5142] = "파멜라 레드패스를 찾아야 합니다.",
    [5143] = "페랄라스에 있는 카리시아 문헌터에게 야생 가죽 조끼와 야생 가죽 투구를 가져가야 합니다. 이 퀘스트를 완료하면 전통 가죽세공술을 배울 수 있지만 용비늘 가죽세공술과 원소 가죽세공술을 배울 수 없습니다. 퀘스트를 시작하기 전에 어떤 가죽 세공술을 배울지 결정하시기 바랍니다.",
    [5144] = "이글거리는 협곡에 있는 사라 터너에게 불의 심장 2개, 물의 보주 2개, 대지의 핵 2개, 바람의 숨결 2개를 가져가야 합니다. 이 퀘스트를 완료하면 원소 가죽세공술을 배울 수 있지만 용비늘 가죽세공술과 전통 가죽세공술을 배울 수 없습니다. 퀘스트를 시작하기 전에 어떤 가죽 세공술을 배울지 결정하시기 바랍니다.",
    [5145] = "단단한 전갈 흉갑 2개와 단단한 전갈 장갑 2개, 그리고 닳아해진 용비늘 10개를 황야의 땅에 있는 토르카프 드래곤아이에 가져가야 합니다. 이 임무를 완료하면 용비늘 가죽세공술을 익히게 되지만 원소 가죽세공술과 전통 가죽세공술은 익힐 수 없게 됩니다. 일을 시작하기 전에 어떤 가죽세공술을 배울지 결정하시기 바랍니다.",
    [5146] = "아라시 고원에 있는 브룸 윈터후프에게 불의 심장 2개, 물의 보주 2개, 대지의 핵 2개, 바람의 숨결 2개를 가져가야 합니다. 이 퀘스트를 완료하면 원소가죽 세공술을 배울 수 있습니다. 이 퀘스트를 완료하면 용비늘 가죽세공술과 전통 가죽세공술을 배울 수 없습니다. 퀘스트를 시작하기 전에 어떤 가죽 세공술을 배울지 결정하시기 바랍니다.",
    [5147] = "아르낙 그림토템을 처치하고 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 그 증거물을 갖다주어야 합니다.",
    [5148] = "가시덤불 골짜기에 있는 세지브에게 야생 가죽 조끼와 야생 가죽 투구를 가져가야 합니다. 이 퀘스트를 완료하면 전통 가죽세공술을 배울 수 있지만 용비늘 가죽세공술과 원소 가죽세공술을 배울 수 없습니다. 퀘스트를 시작하기 전에 어떤 가죽세공술을 배울지 결정하시기 바랍니다.",
