    [5161] = "계속하려면 헬레와 대화하십시오.",
    [5162] = "역병지대로 가서 안돌할에 사는 제지바와 대화하십시오.",
    [5163] = "우미의 기계설인을 가지고 가서 아래 친구들에게 겁을 주어야 합니다. 여명의 설원, 눈망루 마을에 있는 레각키 타나리스의 가젯잔에 있는 스프링클 운고로 분화구, 마샬의 야영지에 있는 퀵실 모두에게 겁을 주고 나서 기계설인을 도로 우미에게 데리고 가야 합니다.",
    [5164] = "제지바의 뒤에 있는 무법의 시대 일람을 읽어야 합니다.",
    [5165] = "정화된 달샘 물을 써서 악령의 숲에 있는 어둠의 요새를 감싸고 있는 화로 4개를 파괴한 후 에메랄드 성소에 있는 그레타 모스후프에게 돌아가야 합니다.",
    [5166] = "오색용군단 흉갑을 제작하려면 다음 재료를 모아 \"조각사\" 제지바에게 가져가야 합니다. 오색 등껍질 1개 반짝이는 오색 비늘 10개 영웅의 피 10개 닳아 해진 누더기골렘 조각 10개",
    [5167] = "오색 파멸자의 다리갑옷을 제작하려면 다음 재료를 모아 \"조각사\" 제지바에게 가져가야 합니다. 오색 등껍질 1개 반짝이는 오색 비늘 10개 영웅의 피 10개 어둠의 허물 5개",
    [5168] = "카를린 레드패스에게 다빌의 성서와 레드패스의 방패를 가져가야 합니다.",
    [5181] = "희망의 빛 예배당에 있는 카를린 레드패스에게 호르구스의 해골과 부러진 마르두크의 검을 가져가야 합니다.",
    [5201] = "리베른 프로스트윈드가 눈사태일족 주술사 5마리와 눈사태일족 펄볼그 5마리를 처치하도록 요청했습니다.",
    [5202] = "자에데나르를 뒤져 이 붉은 열쇠의 용도를 알아내야 합니다.",
    [5203] = "아르코나린을 그녀의 방어구와 라이트포지가 있는 곳까지 호위해 간 후, 함께 어둠의 요새에서 빠져나가야 합니다. 그런 다음, 악령의 숲에 있는 제시 문보우를 찾아가 그녀의 친구들에게 무슨 일이 있었는지 알려 주어야 합니다.",
    [5204] = "자에데나르로 돌아가 서큐버스 라카이아를 처치한 후, 트레이 라이트포지의 유해를 찾아와야 합니다.",
    [5206] = "동부 역병지대에 있는 카를린 레드패스에게 텅빈 해골 5개와 불가사의한 수정을 가져가야 합니다.",
    [5210] = "동부 역병지대에 있는 카를린 레드패스에게 확장된 다로우샤이어 연대기를 가져가야 합니다.",
    [5211] = "15명의 다로우샤이어 주민들의 원혼을 자유롭게 하고 카를린 레드패스에게 돌아가야 합니다.",
    [5212] = "스트라솔름에서 20개의 역병걸린 살덩어리 견본을 베티나 비글징크에게 가져다주어야 합니다. 스트라솔름의 어떤 생물에서든 살덩어리 견본을 구할 수 있을 것 같습니다.",
    [5213] = "스트라솔름으로 가서 지구라트를 조사해야 합니다. 스컬지 자료를 찾아 베티나 비글징크에게 돌아가야 합니다.",
    [5214] = "스트라솔름에서 에즈라 그림의 최고급 담배를 회수하여 스모키 라루에게 가져가야 합니다.",
    [5215] = "서부 역병지대의 서리바람 거점에 있는 대여사제 맥도널과 대화해야 합니다.",
    [5216] = "서부 역병지대의 펠스톤 농장으로 가서 그곳에 있는 가마솥군주를 찾아 물리치십시오. 가마솥군주가 가마솥으로 통하는 열쇠를 지니고 있을 수도 있습니다. 빈 펠스톤 농장 병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.",
    [5217] = "서부 역병지대의 서리바람 야영지에 있는 대여사제 맥도널에게 가득 찬 펠스톤 농장 병을 가져가야 합니다.",
    [5219] = "서부 역병지대의 달슨의 눈물로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 지닌 열쇠를 사용해 가마솥에 접근하십시오. 반드시 달슨의 눈물 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.",
    [5220] = "서부 역병지대의 서리바람 야영지에 있는 대여사제 맥도널에게 가득 찬 달슨의 눈물 혼합물을 가져가야 합니다.",
    [5222] = "서부 역병지대의 고통의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 고통의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.",
    [5223] = "서부 역병지대의 서리바람 야영지에 있는 대여사제 맥도널에게 가득 찬 고통의 흉가 혼합물을 가져가야 합니다.",
    [5225] = "서부 역병지대의 가론의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 가론의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.",
    [5226] = "서부 역병지대의 서리바람 야영지에 있는 대여사제 맥도널에게 가득 찬 가론의 흉가 혼합물을 가져가야 합니다.",
