    [5229] = "서부 역병지대의 펠스톤 농장으로 가서 그곳에 있는 가마솥군주를 찾아 물리치십시오. 가마솥군주가 가마솥으로 통하는 열쇠를 지니고 있을 수 있습니다. 반드시 빈 펠스톤 농장 병을 가지고 가서 가마솥 안에 있는 독의 견본을 확보해야 합니다.",
    [5230] = "서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 펠스톤 농장 병을 가져가야 합니다.",
    [5231] = "서부 역병지대의 달슨의 눈물로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 달슨의 눈물 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.",
    [5232] = "서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 달슨의 눈물 혼합물을 가져가야 합니다.",
    [5233] = "서부 역병지대의 고통의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 고통의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.",
    [5234] = "서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 고통의 흉가 혼합물을 가져가야 합니다.",
    [5235] = "서부 역병지대의 가론의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 가론의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.",
    [5236] = "서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 가론의 흉가 혼합물을 가져가야 합니다.",
    [5241] = "카를린 레드패스를 찾아야 합니다.",
    [5242] = "무라와 살리라, 그리고 어둠의 군주 펠단을 처치하십시오. 그리고 그 증거로 펠단의 머리카락을 악령의 숲에 있는 그레타 모스후프에게 가져가야 합니다.",
    [5243] = "북쪽에 있는 스트라솔름으로 가서 도시 어딘가에 흩어진 보급품 상자를 찾아 스트라솔름 성수 5병을 가져와야 합니다. 성수를 충분히 모으고 나면 존경받는 리어니드 바돌로매에게 돌아가야 합니다.",
    [5244] = "별똥별 마을에 있는 야론 스톤셰이퍼와 대화하십시오.",
    [5245] = "야론의 곡괭이를 사용해 귀족 유물 조각 4개를 찾아 동부 역병지대에 있는 아우로라 스카이콜러에 갖다주어야 합니다.",
    [5246] = "아즈샤라에 있는 진말로의 신전에서 귀족의 성서를 찾아야 합니다. 동부 역병지대의 북부관문 경비탑 근처에 있는 아우로라 스카이콜러에게 가져가십시오.",
    [5247] = "마력 깃든 토륨 주괴 1개와 회복의 수정 5개, 그리고 혈투의 웅덩이 물병을 동부 역병지대의 북부관문 경비탑 근처에 있는 아우로라 스카이콜러에게 가져가야 합니다.",
    [5248] = "진말로의 수정을 여명의 설원에 있는 켈테릴 호수로 갖고 가서 당신과 대화를 하고자 하는 명가의 영혼을 찾아야 합니다.",
    [5249] = "여명의 설원에 있는 별똥별 마을에서 윈드 나이트체이서와 대화하십시오.",
    [5250] = "여명의 설원에서 별똥별 마을을 찾아 윈드 나이트체이서와 대화하십시오.",
    [5251] = "스트라솔름으로 가서 붉은십자군의 기록관, 갈포드를 찾아서 그를 처치하고 붉은십자군 기록을 불태워 버려야 합니다.",
    [5252] = "별똥별 마을에 있는 윈드 나이트체이서와 대화해 진말로의 수정을 어디에 두어야 하는지 물어보십시오.",
    [5253] = "다르나서스에 있는 대드루이드 판드랄 스테그헬름에게 진말로의 수정을 갖다주어야 합니다.",
    [5261] = "이건 펠트스키너와 얘기해야 합니다.",
    [5262] = "동부 역병지대에 있는 공작 니콜라스 즈바른호프에게 발나자르의 혼을 가져가야 합니다.",
    [5263] = "스트라솔름으로 가서 남작 리븐데어를 처치하고 그의 혼을 공작 니콜라스 즈바른호프에게 가져가야 합니다.",
    [5264] = "교회 안에 있는 맥스웰 티로서스 경과 대화해야 합니다.",
    [5265] = "여명회의 궤를 열고 보상을 받아야 합니다.",
    [5281] = "스트라솔름 주변에서 목격된다고 알려진 에간을 찾아야 합니다.",
    [5282] = "스트라솔름 시민의 영혼과 원혼들에게 에간의 제령포를 사용해야 합니다. 원혼들이 그들을 가두고 있던 감옥에서 풀려나면 다시 총을 사용하여 그들에게 자유를 선사하십시오! 15명의 잠 못드는 영혼을 자유롭게 하고 에간에게 돌아가야 합니다.",
    [5283] = "방어구제작자가 되려면 화려한 미스릴 투구 4개, 화려한 미스릴 장화 2켤레, 화려한 미스릴 흉갑 1벌을 만들어 그룸누스에게 가져가야 합니다.",
    [5284] = "무기제작자가 되려면 달의 강철 브로드소드 4자루, 큰 철제 도끼 4자루, 견고한 미스릴 도끼 2자루, 검은 대형 철퇴 2자루를 만들어 이로누스에게 가져가야 합니다.",
    [5301] = "방어구제작자가 되려면 화려한 미스릴 투구 4개, 화려한 미스릴 장화 2켤레, 화려한 미스릴 흉갑 1벌을 만들어 오코토스에게 가져가야 합니다.",
    [5302] = "무기제작자가 되려면 달의 강철 브로드소드 4자루, 큰 철제 도끼 2자루, 견고한 미스릴 도끼 2자루, 검은 대형 철퇴 2자루를 만들어 보르고쉬에게 가져가야 합니다.",
    [5305] = "스트라솔름으로 가서 진홍십자군 대장장이를 처치하고 진홍십자군 대장장이의 작업복을 가지고 릴리스에게 돌아가야 합니다.",
    [5306] = "검은바위 첨탑으로 가서 어둠사냥꾼 보쉬가진을 처치하고 보쉬가진의 뱀돌을 킬램에게 갖다주어야 합니다.",
    [5307] = "스트라솔름에서 검은호위대 검제작자를 찾아 그를 처치하고 검은호위대 휘장을 회수한 후, 세릴 스컬지베인에게 갖다주어야 합니다.",
    [5321] = "케를로니안 에버셰이드를 릴라드리스 문리버가 있는 남쪽으로 호위하며, 어둠의 해안에서 그의 가방을 찾아야 합니다.",
    [5341] = "스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 재산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 임무를 완수한 후 알렉시 바로브에게 돌아가야 합니다.",
    [5342] = "얼라이언스 영토인 서리바람 야영지로 가서 웰던 바로브를 암살해야 합니다. 그 증거로 그의 머리카락을 가지고 알렉시 바로브에게 돌아가십시오. 얼라이언스 쓰레기들이 웰던을 보호하고 있을 테니 조심해야 합니다.",
    [5343] = "스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 유산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 이 임무를 완수한 후 웰던 바로브에게 돌아가야 합니다.",
    [5344] = "호드의 영토인 보루로 가서 알렉시 바로브를 암살하십시오. 그 증거로 그의 머리카락을 가지고 웰던 바로브에게 돌아가십시오. 더러운 호드가 알렉시를 보호하고 있을 테니 조심해야 합니다.",
    [5361] = "절벽파수꾼 롱혼의 보고서를 잊혀진 땅의 침묵의 초소에 있는 나타카 롱혼에게 가져가야 합니다.",
    [5381] = "천둥도끼 요새에서 악마의 상자를 찾아서 그늘수렵 마을에 있는 타이가 와이즈메인에게 가져가십시오. 악마의 곡괭이도 함께 돌려줘야 합니다.",
    [5382] = "스칼로맨스 내에서 학자 테올렌 크라스티노브를 찾아 처치한 후 에바 사크호프의 유해와 루시엔 사크호프의 유해를 불태우십시오. 임무를 완수하면 에바 사크호프에게 돌아가야 합니다.",
    [5384] = "순결한 피를 가지고 스칼로맨스로 돌아가야 합니다. 사자의 창을 찾아 사자의 화롯불에 순결한 피를 올려 놓으면 키르토노스가 영혼을 차지하기 위해 나타납니다. 용맹하게 싸우고 단 한 발짝도 물러서지 마십시오! 키르토노스를 처치한 후 에바 사크호프에게 돌아가야 합니다.",
    [5385] = "트레이 라이트포지의 유해를 악령의 숲에 있는 제시 문보우에게 가져다주어야 합니다.",
    [5386] = "그늘수렵 마을에 있는 지나르질렌과 대화한 후 나타카 롱혼에게 붉은복어 2마리를 가져가야 합니다.",
    [5441] = "작업반장의 몽둥이를 가지고 가서 자고 있는 게으른 일꾼에게 사용해야 합니다. 일꾼 5명을 깨운 다음 시험의 골짜기에 있는 작업반장 타즈릴에게 돌아가 몽둥이를 돌려줘야 합니다.",
    [5461] = "아라시 고원에 있는 스트롬가드 폐허로 가십시오. 스트롬가드에서 추억의 유품을 찾아야 합니다. 그런 물건을 찾으면 집정관 마르듀크에게 돌아가야 합니다.",
    [5462] = "동부 역병지대에 있는 희망의 빛 예배당으로 가서 존경받는 리어니드 바돌로매를 찾아서 추억의 유품을 보여 주고 알아낸 사실에 대해 모두 얘기해야 합니다.",
    [5463] = "스트라솔름으로 가서 메네실의 선물을 찾아서 그 부정한 땅 위에 추억의 유품을 두어야 합니다.",
    [5464] = "동부 역병지대에 있는 리어니드 바돌로매에게 영혼이 씌인 유품을 가져가야 합니다.",
    [5465] = "카엘 다로우에 있는 집정관 마르듀크에게 돌아가십시오. 그에게 영혼이 씌인 유품을 보여줘야 합니다.",
    [5466] = "스칼로맨스에서 라스 프로스트위스퍼를 찾아야 합니다. 영혼이 쓰인 유품을 언데드 상태인 라스의 얼굴에 사용하십시오. 그를 산 자로 되돌리는 데 성공하면 그를 쓰러뜨리고 사람이 된 라스 프로스트위스퍼의 머리카락을 가지고 집정관 마르듀크에게 가야 합니다.",
    [5481] = "어둠풀 3개를 채집해 브릴 공동묘지에 있는 초보연금술사 홀랜드에게 가져가야 합니다.",
    [5482] = "초급연금술사 홀랜드에게 죽음풀 10개를 모아서 가져가야 합니다.",
    [5501] = "코르메크의 오두막에 있는 비블리 푸츠버클에게 코도 무덤에서 코도 뼈 10개를 가져가야 합니다.",
    [5504] = "서부 역병지대의 보루에 있는 병참장교 하사나에게 은빛 여명회 명예 휘장 10개를 가져가야 합니다.",
    [5507] = "서부 역병지대의 서리바람 야영지에 있는 병참장교 라이트스파크에게 은빛 여명회 명예 휘장 10개를 가져가야 합니다.",
    [5513] = "동부 역병지대의 희망의 빛 예배당에 있는 병참장교 미란다 브리치락에게 은빛 여명회 명예 휘장 10개를 가져가야 합니다.",
    [5514] = "가젯잔에 있는 크린클 굿스틸에게 15골드와 함께 마력 깃든 뼈조각을 가져가야 합니다.",
    [5515] = "스칼로맨스에서 잔다이스 바로브를 찾아 처치해야 합니다. 그녀의 시체에서 소름끼치는 크라스티노브의 가방을 찾은 후 에바 사크호프에게 가져가야 합니다.",
    [5517] = "동부 역병지대의 희망의 빛 예배당에 있는 병참장교 미란다 브리치락에게 은빛 여명회 명예 휘장 25개를 가져가야 합니다.",
    [5518] = "룬무늬 두루마리 4개, 튼튼한 가죽 8장, 룬문자 실타래 2개, 그리고 오우거 타닌을 노트 팀블잭에게 가져가야 합니다. 노트 팀블잭은 혈투의 전장에 있는 고르독일족 은신처 구석에 족쇄에 묶여 있습니다.",
    [5521] = "서부 역병지대의 서리바람 거점에 있는 병참장교 라이트스파크에게 은빛 여명회 명예 휘장 25개를 가져가야 합니다.",
    [5522] = "동부 역병지대에 있는 리어니드 바돌로매에게 얼어붙은 알을 가져가야 합니다.",
    [5524] = "서부 역병지대의 보루에 있는 병참장교 하사나에게 은빛 여명회 명예 휘장 25개를 가져가야 합니다.",
    [5526] = "혈투의 전장에서 악령덩굴 조각을 채취하십시오. 칼날바람 알진을 물리쳐야만 얻을 수 있을 것입니다. 정화의 성물함에 단단히 봉인한 후, 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다.",
