    [6481] = "마력 깃든 리조나이트 수정으로 리조나이트 광석을 연 다음 고게로크를 처치해야 합니다. 그를 처치했다는 소식과 마력 깃든 리조나이트 수정을 들고 모르로갈에게 돌아가십시오.",
    [6482] = "루울을 호위해 탈출한 후, 토막나무 주둔지에 있는 야마 스노우후프와 대화하십시오.",
    [6501] = "전 세계를 뒤져 용의눈 조각의 힘을 복원할 수 있는 자를 찾아야 합니다. 이와 관련해 알고 있는 유일한 정보는 그러한 자들이 존재한다는 것뿐입니다.",
    [6502] = "사령관 드라키사스에게서 검은용 용사의 피를 가져와야 합니다. 드라키사스는 검은바위 첨탑의 승천의 전당 뒤에 있는 알현실에 있습니다.",
    [6503] = "잿빛 골짜기 정찰꾼 9명을 처치한 후 토막나무 주둔지에 있는 쿠레이빈에게 돌아가십시오.",
    [6504] = "잃어버린 벌목기 조작설명서 열 두쪽을 찾아서 1장, 2장, 그리고 3장으로 합쳐야 합니다. 그런 다음 토막나무 주둔지 근처에 있는 구르다 레이지스카에게 돌려 주어야 합니다.",
    [6521] = "사절 말킨을 처치한 다음 언더시티에 있는 바리마트라스에게 그의 머리카락을 증거로 가져가야 합니다.",
    [6522] = "작은 두루마리를 언더시티에 있는 바리마트라스에게 가져가야 합니다.",
    [6523] = "카야 플랫후프를 아파라제 야영지까지 호위한 다음 돌발톱 산맥 남동쪽 가장자리에 있는 마카바 플랫후프에게 소식을 전하러 가야 합니다.",
    [6541] = "불모의 땅 북부의 감시탑에 있는 카드라크에게 보고하십시오.",
    [6542] = "불모의 땅 북부의 감시탑에 있는 카드라크에게 보고하십시오.",
    [6543] = "먼저 보고서 뭉치를 여십시오. 전쟁노래부족 길잡이, 전쟁노래부족 정찰병, 그리고 전쟁노래부족 척후병에게 전쟁노래부족 보고서를 가져가야 합니다. 그들의 보고 내용을 담고 있는 최신정보 3개를 받아서 불모의 땅 북부 감시탑에 있는 카드라크에게 돌아가십시오.",
    [6544] = "은빛날개 전초기지와 두리엘 문파이어를 공격하는 토렉을 호위한 후, 토막나무 주둔지에 있는 에르톡 레이지터스크에게 보고하십시오.",
    [6548] = "그림토템부족 약탈자 8명과 그림토템부족 용병 6명을 처치한 다음 돌발톱 산맥 동남쪽 가장자리에 있는 마카바 플랫후프에게 돌아가야 합니다.",
    [6561] = "황혼의 군주 켈리스를 처치하고 그 증거로 그의 머리카락을 썬더 블러프에 있는 바샤나 룬토템에게 가져가야 합니다.",
    [6562] = "잿빛 골짜기에 있는 제네우 생크리와 대화하십시오.",
    [6563] = "잿빛 골짜기에 있는 제네우 생크리에게 아쿠마이의 사파이어 20개를 가져가야 합니다.",
    [6564] = "축축한 메모를 잿빛 골짜기의 제네우 생크리에게 가져가십시오.",
    [6565] = "검은심연 나락에 있는 로구스 제트를 처치한 후 잿빛 골짜기의 제네우 생크리에게 돌아가십시오.",
    [6566] = "스랄의 이야기를 들어야 합니다.",
    [6567] = "렉사르를 찾아야 합니다. 그의 행방은 대족장이 설명해 주었습니다. 돌발톱 산맥과 페랄라스 사이에 있는 잊혀진 땅의 길에서 찾아 보십시오.",
    [6568] = "서부 역병지대에 있는 노파 미란다에게 렉사르의 유서를 전달해야 합니다.",
    [6569] = "검은바위 첨탑으로 가서 검은 용혈족의 눈동자 20개를 모아서 노파 미란다에게 돌아가야 합니다.",
    [6570] = "먼지진흙 습지대에 있는 용의 둥지로 가서 엠버스트라이프의 굴을 찾아야 합니다. 안으로 들어가서 용족 파멸의 아뮬렛을 착용하고 엠버스트라이프와 대화해야 합니다.",
    [6571] = "토막나무 주둔지의 록케 오카르를 위해 전쟁노래부족 보급품을 모아 오십시오. 전쟁노래부족 톱날, 전쟁노래부족 도끼 상자, 전쟁노래부족 기름, 그리고 벌목용 밧줄을 가져와야 합니다.",
    [6582] = "여명의 설원에서 찾을 수 있는 푸른용군단의 용사 스크라이어를 찾아 처치해야 합니다. 그의 <name>체에서 해골을 수습해서 엠버스트라이프에게 돌아가야 합니다.",
    [6583] = "녹색용군단의 우두머리 솜누스를 처치한 후 그의 해골을 수습해서 엠버스트라이프에게 돌아가야 합니다.",
    [6584] = "노즈도르무의 자손인 크로날리스가 타나리스 사막에 있는 <name>간의 동굴을 지키고 있습니다. 그를 처치한 후 그의 해골을 엠버스트라이프에게 가져가야 합니다.",
    [6585] = "그림 바톨로 가서 붉은용군단의 우두머리 악트로즈를 찾아 그를 처치한 다음 그의 해골을 수습하여 엠버스트라이프에게 돌아가야 합니다.",
    [6601] = "이제 가면놀이는 끝난 것 같습니다. 노파 미란다가 만든 용족 파멸의 아뮬렛이 검은바위 첨탐 안에서 원래 구실을 하지 않는 것을 알고 있습니다. 아마도 렉사르를 찾아가 곤경에 처한 상황을 설명하는 것이 좋겠습니다. 렉사르에게 흐릿한 비룡불꽃 아뮬렛을 보여주면 아마도 필요한 게 무엇인지 알 수 있을 겁니다.",
    [6602] = "검은바위 첨탑으로 가서 사령관 드라키사스를 처치하고 사령관의 피를 모아 렉사르에게 가져가야 합니다.",
    [6603] = "여명의 설원 간헐천 부근에 있는 도노바 스노우덴을 찾아가야 합니다.",
    [6604] = "별똥별 마을에 있는 야론 스톤셰이퍼를 만나야 합니다.",
    [6605] = "악령의 숲에 있는 위나 해저드를 만나야 합니다.",
    [6607] = "아래 물고기들을 모두 잡아 내트 페이글에게 돌아가야 합니다. 슬픔의 늪의 안개갈대 해안에 사는 안개갈대 황새치 잊혀진 땅의 살데리스 해안에 사는 살데리스 아귀 페랄라스의 베르단티스 강에 사는 페랄라스 참치 가시덤불 골짜기의 폭풍 해안에 사는 폭풍 해안 푸른도루묵 위 물고기를 모두 얻은 후 내트 페이글에게 돌아가십시오.",
    [6608] = "루막에 말에 의하면 그는 더 이상 당신의 낚시 실력 향상에 도움을 줄 수 없는 듯합니다. 아마 테라모어로 가라는 말인 것 같습니다. 남쪽에 있는 섬 어디엔가에서 낚시를 하고 있을 루막의 인간 친구 내트 페이글을 찾아 보십시오.",
    [6609] = "칼림도어로 가서 해안 도시인 테라모어로 가야 합니다. 그곳 마을에서 남쪽에 있는 섬을 찾아야 합니다. 내트 페이글이 당신을 기다리고 있습니다!",
    [6610] = "더지 퀵클레이브가 다음 재료를 구해 오라고 합니다. 거대한 알 12개... 타나리스에 떠돌고 있는 로크와 같은 커다란 새에게서 구할 수 있습니다. 고소한 조갯살 10개... 조개를 열어서 찾을 수 있습니다. 알터랙 스위스 치즈 20개... 아무 상인이나 붙잡고 알아보십시오. 모든 재료를 모아서 더지에게 돌아가야 합니다.",
    [6611] = "타나리스 사막에 있는 가젯잔으로 가서 더지 퀵클레이브를 만나 당신의 요리 실력 향상에 대해 대화를 나누어야 합니다.",
    [6612] = "타나리스 사막에 있는 가젯잔으로 가서 더지 퀵클레이브를 만나 당신의 요리 실력 향상에 대해 대화를 나누어야 합니다.",
    [6621] = "썩은나무일족 토템고분에 카랑의 깃발을 꽂은 다음 펄볼그들이 깃발을 부수지 못하도록 막아야 합니다. 족장 머구트가 나타나면 그를 물리치고 머구트의 토템을 조람가르 전초기지의 카랑 아마카르에게 가져가야 합니다.",
    [6622] = "응급 붕대로 상처를 치료해서 환자를 구해야 합니다. 환자 6명이 죽기 전에 15명을 구해야 합니다. 부상자 치료 우선 순위를 기억해야 합니다! 위독한 부상병이 가장 빨리 사망하고 그 다음으로 위태로운 부상병이 사망합니다. 부상병들이 제일 늦게 사망하므로 위독한 부상병과 위태로운 부상병을 먼저 구해야 합니다.",
    [6623] = "아라시 고원에 있는 해머폴로 가서 호드 응급의학회의 일원이 되는 방법에 대해 의사 그레고리 빅터와 대화를 나누어야 합니다.",
    [6624] = "응급 붕대로 상처를 치료해서 환자를 구해야 합니다. 환자 6명이 죽기 전에 15명을 구해야 합니다. 부상자 치료 우선 순위를 기억해야 합니다! 위독한 부상병이 가장 빨리 사망하고 그 다음으로 위태로운 부상병이 사망합니다. 가벼운 부상을 입은 부상병이 제일 늦게 사망하므로 위독한 부상병과 위태로운 부상병을 먼저 구해야 합니다.",
    [6625] = "먼지진흙 습지대에 있는 테라모어로 가서 얼라이언스 응급의학회의 일원이 되는 방법에 대해 의사 구스타프 밴하우젠과 대화를 나누어야 합니다.",
    [6626] = "가시덩굴일족 전투호위병과 가시덩굴일족 가시마술사, 그리고 죽음의 머리교 신도를 각각 8마리씩 죽인 후 가시덩굴 구릉 입구 근처에 있는 미리암 문싱어에게 돌아가야 합니다.",
    [6627] = "브라우그 딤스피릿의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 브라우그 딤스피릿은 돌발톱 산맥에 있을 것입니다.",
    [6628] = "파쿠알 핀탈라스의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 파쿠알 핀탈라스는 언더시티에 있을 것입니다.",
    [6629] = "그룬디히 다크클라우드와 그림토템부족 투사 6명을 처치한 다음 돌발톱 산맥 남동쪽 끄트머리에 있는 마카바 플랫후프에게 돌아가야 합니다.",
    [6641] = "머그래쉬가 화로로 접근하는 동안 안전하게 보호하고, 그를 도와 화로를 꺼야 합니다. 그런 다음 나가와 맞서 싸우는 동안 그를 보호하십시오. 성공하면 조람가르 전초기지로 돌아와 전쟁노래부족 길잡이에게 채찍꼬리 보르샤의 죽음을 보고하십시오.",
    [6661] = "쥐잡는 사나이의 피리를 사용해 깊은굴쥐 5마리를 잡은 후 몬티에게로 데리고 가야 합니다. 다 끝난 후에는 피리를 몬티에게 되돌려줘야 합니다.",
    [6662] = "스톰윈드 깊은굴 지하철에 있는 닙시에게 이상한 고기 상자를 가져다 주어야 합니다.",
    [6681] = "힐스브래드의 구릉지에 숨어 있는 라벤홀트 장원의 파라드에게 라벤홀트의 인장을 가져가야 합니다. 라벤홀트 장원의 입구 근처에서 자신의 실력을 증명할 상자를 발견하게 될 것이며 어떤 기술을 사용하여 이를 증명해야 할지 준비해야 합니다.",
    [6721] = "돌라나르에 있는 다잘라와 대화하십시오.",
    [6722] = "돌라나르에 있는 다잘라와 대화하십시오.",
    [6761] = "다르나서스의 세나리온 자치령에 있는 마스렌길 베어워커와 대화하십시오.",
    [6762] = "달의 숲, 나이트헤이븐에 있는 라빈 사투르나와 대화하십시오. 달의 숲은 악령의 숲과 여명의 설원 사이에 있으며 나무구렁 요새에서 나가는 길을 따라가면 됩니다.",
    [6804] = "동부 역병지대에 있는 역병에 걸린 정령들에게 넵튤론의 상을 사용하십시오. 아즈샤라에 있는 군주 히드락시스에게 불협의 팔보호구 12개와 넵튤론의 상을 가져가야 합니다.",
    [6805] = "먼지 폭풍 15마리와 우레의 모래정령 15마리를 처치하고 아즈샤라에 있는 군주 히드락시스에게 돌아가야 합니다.",
    [6821] = "아즈샤라에 있는 군주 히드락시스에게 엠버시어의 눈을 가져가야 합니다.",
    [6822] = "불의 군주 1마리, 용암거인 1마리, 고대의 심장부 사냥개 1마리, 굽이치는 용암 정령 1마리를 처치한 후 아즈샤라에 있는 군주 히드락시스에게 돌아가야 합니다.",
    [6823] = "히드락시스 물의 군주들로부터 우호적인 평판을 얻은 후 아즈샤라에 있는 군주 히드락시스와 대화해야 합니다.",
    [6824] = "아즈샤라에 있는 군주 히드락시스에게 루시프론, 설퍼론, 게헨나스, 샤즈라의 손을 가져가야 합니다.",
    [6844] = "달의 숲의 나이트헤이븐 마을에 있는 세나리온 의회의 기록관, 움버에게 딱딱한 실리시드 조각을 가져가야 합니다.",
    [6845] = "달의 숲의 나이트헤이븐에 있는 라빈 사투르나와 대화해야 합니다.",
    [6921] = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 심연의 핵을 가져가야 합니다.",
    [6922] = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 이상한 물구슬을 가져가야 합니다.",
    [6981] = "톱니항으로 가서 빛나는 조각에 대해 자세히 얘기해 줄 수 있는 이를 찾으십시오. 그에게 지시를 받아, 빛나는 조각을 전달해야 합니다.",
    [6982] = "던 발다르에 있는 얼라이언스 병참장교에게 얼음이빨 광산 보급품 10개를 가져가야 합니다.",
    [6985] = "서리늑대 요새에 있는 서리늑대 병참장교에게 깊은무쇠 광산 보급품 10개를 가져가야 합니다.",
    [7001] = "알터랙 계곡에서 서리늑대를 찾아야 합니다. 발견한 서리늑대 근처에서 서리늑대 재갈을 사용하십시오. 그러면 서리늑대는 당신을 따라다니기 시작할 것입니다. 서리늑대부족 야수관리인에게 돌아가 서리늑대를 포획한 공로를 인정받으십시오.",
    [7003] = "페랄라스에서 눈에 띄는 아무 거인에게나 조브린의 형상축소기를 사용해 좀 더 다루기 쉬운 형태로 변환하십시오. 페랄라스의 잊혀진 해안 부두에 있는 조브린 팬대즐에게 변형된 거인들에게서 얻을 수 있는 축소화 잔류물 15개를 가져가야 합니다.",
    [7027] = "알터랙 계곡에 돌아다니는 알터랙 산양을 찾아야 합니다. 알터랙 산양을 찾으면 그 근처에서 스톰파이크 조련용 목줄을 사용해 산양을 길들이십시오. 그러면 야수 관리인에게 돌아갈 때 따라올 것입니다. 알터랙 산양 포획을 인정받기 위해서는 야수 관리인과 대화해야 합니다.",
    [7028] = "트라드릭 수정 조각상 25개를 모아서 잊혀진 땅에 있는 윌로우에게 가져가야 합니다.",
    [7029] = "마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다. 오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다. 녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 그늘수렵 마을에 있는 바르크 배틀스카에게 돌아가야 합니다.",
    [7041] = "마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다. 오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다. 녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 나이젤의 야영지에 있는 탈렌드리아에게 돌아가야 합니다.",
    [7044] = "셀레브라스의 홀 조각인 셀레브리안 마법봉과 셀레브리안 다이아몬드를 찾아야 합니다. 셀레브라스와 대화를 나눌 방법을 찾아야 합니다.",
    [7046] = "회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다. 의식을 마친 후 그와 대화하십시오.",
    [7064] = "공주 테라드라스를 해치우고 잊혀진 땅의 그늘수렵 마을 근처에 있는 셀렌드라에게 돌아가야 합니다.",
    [7065] = "공주 테라드라스를 해치우고 잊혀진 땅의 나이젤의 야영지에 있는 수호자 마란디스를 찾아가야 합니다.",
    [7066] = "달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다.",
    [7067] = "추방자의 지시서를 읽은 다음 마라우돈에서 결속의 아뮬렛을 획득해서 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다.",
    [7068] = "마라우돈에서 음영석 조각 10개를 모아서 오그리마에 있는 우텔나이에게 가져가야 합니다.",
    [7070] = "마라우돈에서 음영석 조각 10개를 모아서 먼지진흙 습지대의 해안에 위치한 테라모어에 있는 대마법사 테르보쉬에게 가져가야 합니다.",
    [7081] = "호드의 무덤을 공격한 다음 알터랙 산맥에 있는 하사관 두르겐 스톰파이크에게 돌아가야 합니다.",
    [7082] = "얼라이언스가 점령하고 있는 무덤을 공격한 다음 알터랙 산맥에 있는 하사관 티카 블러드스날에게 돌아가야 합니다.",
    [7101] = "적군의 보초탑을 점령한 다음 알터랙 산맥에 있는 하사관 티카 블러드스날에게 돌아가야 합니다.",
    [7102] = "적군의 보초탑이나 참호에 있는 깃발을 파괴한 후 알터랙 산맥에 있는 하사관 두르겐 스톰파이크에게 돌아가야 합니다.",
    [7121] = "스톰파이크 병참장교와 대화해야 합니다.",
    [7122] = "스톰파이크 경비대가 점령하지 않은 광산을 점령한 후 알터랙 산맥에 있는 하사관 두르겐 스톰파이크에게 돌아가야 합니다.",
    [7123] = "서리늑대 병참장교와 대화하십시오.",
    [7124] = "광산 하나를 점령한 후 알터랙 산맥에 있는 하사관 티카 블러드스날에게 돌아가야 합니다.",
    [7141] = "알터랙 계곡으로 진입하여 호드 사령관인 드렉타르를 처치하고, 알터랙 산맥에 있는 발굴조사단장 스톤휴어에게 돌아가야 합니다.",
    [7142] = "알터랙 계곡으로 진입하여 얼라이언스 사령관인 반다르 스톰파이크를 처치하고, 알터랙 산맥에 있는 보그가 데스그립에게 돌아가야 합니다.",
    [7161] = "알터랙 계곡의 서리늑대 요새 남동쪽에 위치한 자갈발 동굴로 가서 서리늑대부족 깃발을 찾아 전투대장 락그론드에게 가져가야 합니다.",
    [7162] = "알터랙 계곡에 있는 던 발다르에서 남서쪽에 위치한 얼음날개 동굴로 가서 스톰파이크 깃발을 찾아 알터랙 산맥에 있는 부관 해거딘에게 돌아가야 합니다.",
    [7181] = "전설에 의하면 겨울도끼 트롤들의 막강한 지도자가 나타나면, 그것은 알터랙 계곡에 사는 모든 생명체들을 학살하기 위해서라고 합니다. 콜라크가 나타나면 그를 처치한 후 전투대장 락그론드에게 돌아가야 합니다.",
    [7201] = "검은바위 나락으로 가서 원소의 정수 10개를 회수해야 합니다. 먼저 골렘이나 골렘 제조자부터 찾아보십시오. 비비안 라그레이브가 정령에 대해 중얼거리듯 얘기한 것이 기억납니다.",
    [7202] = "전설에 의하면 겨울도끼 트롤들의 막강한 지도자가 나타나면, 그것은 알터랙 계곡에 사는 모든 생명체들을 학살하기 위해서라고 합니다. 콜라크가 나타나면 그를 처치한 후 알터랙 산맥에 있는 부관 해거딘에게 돌아가야 합니다.",
    [7223] = "던 발다르에 있는 멀고트 딥포지에게 방어구 조각 20개를 가져가야 합니다.",
    [7224] = "서리늑대 마을에 있는 대장장이 렉자르에게 방어구 조각 20개를 가져가야 합니다.",
    [7241] = "알터랙 산맥에 있는 알터랙 계곡으로 가십시오. 입구 바깥에 서 있는 전투대장 락그론드를 찾아 서리늑대부족 병사로서의 경력을 쌓도록 하십시오. 알터랙 계곡은 타렌 밀농장 북쪽의 알터랙 산맥 기슭에 있습니다.",
    [7261] = "힐스브래드 구릉지에 있는 알터랙 계곡으로 가야 합니다. 알터렉 계곡으로 들어서는 입구 터널 밖에 있는 부관 해거딘을 찾아 대화하십시오. 브론즈비어드의 영광을 위하여!",
    [7281] = "스톰파이크 영토로 쳐들어가 얼라이언스 사령관 칼 필립스를 처치해야 합니다. 임무를 완수하면 호드 사령관 루이스 필립스에게 돌아가십시오.",
    [7282] = "서리늑대부족 진영으로 들어가 사령관 루이스 필립스를 처치한 후 얼라이언스 지휘관 칼 필립스에게 돌아가야 합니다.",
    [7301] = "서리늑대 부족의 진영으로 가서 편대사령관 실도르, 편대사령관 비포르, 그리고 편대사령관 이크만을 찾아야 합니다. 임무를 완수하면 지휘관 더피에게 돌아가십시오.",
    [7302] = "호드 편대사령관 구스, 제즈톨, 그리고 멀베릭이 어떻게 되었는지 알아내야 합니다. 임무를 완수하면 지휘관 멀포트에게 돌아가십시오.",
    [7321] = "타렌 밀농장에 있는 크리스토프 제프코트에게 거북이 고기 10개와 독특한 양념을 가져가야 합니다.",
    [7361] = "알터랙 계곡에 있는 얼라이언스 진영의 나이트 엘프 플레이어를 쓰러뜨리라는 임무를 받았습니다. 나이트 엘프를 처치하고 서리늑대 요새에 있는 나자크 헥센에게 나이트 엘프 머리카락을 가져가야 합니다.",
    [7362] = "알터랙 계곡에 있는 얼라이언스 진영의 노움 플레이어를 쓰러뜨리라는 임무를 받았습니다. 노움을 처치하고 서리늑대 요새에 있는 라바크 그림토템에게 노움 머리카락 뭉치를 가져가야 합니다.",
    [7363] = "알터랙 계곡에 있는 얼라이언스 진영의 인간 플레이어를 쓰러뜨리라는 임무를 받았습니다. 인간을 처치하고 지휘관 루이스 필립스에게 인간 뼛조각 하나를 가져가야 합니다. 지휘관 루이스 필립스는 최전선과 서리늑대 요새 사이를 거닐고 있을 것입니다. 인간의 본질을 치유할 날이 얼마 남지 않았습니다!",
    [7366] = "알터랙 계곡에 있는 호드 진영의 언데드 플레이어를 쓰러뜨리라는 임무를 받았습니다. 언데드를 처치하고 포세이큰 심장을 얼라이언스 지휘관 칼 필립스에게 가져가야 합니다. 얼라이언스 사령관 칼 필립스는 벌목지와 광산 사이를 정찰하고 있습니다.",
    [7381] = "피의 광전사 콜라크가 투쟁의 벌판에 다시 나타나면 그를 찾아 처치하십시오. 언덕마루 구릉지에 있는 전투대장 락그론드에게 콜라크의 해골을 가져가야 합니다.",
    [7382] = "피의 광전사 콜라크가 투쟁의 벌판에 다시 나타나면 그를 찾아 처치하십시오. 알터랙 산맥에 있는 부관 해거딘에게 콜라크의 해골을 가져가야 합니다.",
    [7383] = "자수정 약병을 채운 다음 돌라나르에 있는 코리드라스 문레이지에게 가져가야 합니다.",
    [7441] = "혈투의 전장으로 가서 푸실린이라는 임프를 찾으십시오. 어떤 수단을 써서라도 아즈토리딘의 마법서를 돌려받아야 합니다. 마법서를 회수하면 페랄라스의 라리스 정자에 있는 아즈토리딘에게 돌아가야 합니다.",
    [7461] = "이몰타르의 감옥에 힘을 공급하는 다섯 개의 수정탑을 둘러싼 수호자들을 처치해야 합니다. 수정탑의 마력이 약해지면 이몰타르를 둘러싼 마법진도 분산될 것입니다. 이몰타르의 감옥에 들어가 그 심장부에 서 있는 사악한 이몰타르를 처치하고, 마지막으로 도서관에 있는 토르텔드린 왕자와 맞서 싸우십시오. 이 임무를 완수하면 안마당에 있는 셴드랄라 고대인에게 돌아가야 합니다.",
    [7463] = "혈투의 전장에 있는 굽이나무 지구로 가서 물의 정령인 히드로스폰을 처치하십시오. 히드로스폰의 정수를 가지고 도서관에 있는 현자 리드로스에게 돌아가야 합니다.",
    [7481] = "혈투의 전장을 뒤져 텔미우스 드림시커를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 모자케 야영지에 있는 현자 코로루스크에게 돌아가야 합니다.",
    [7482] = "혈투의 전장을 뒤져 텔미우스 드림시커를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 페더문 요새에 있는 학자 룬쏜에게 돌아가야 합니다.",
    [7483] = "신속의 성서, 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 2개, 그리고 영웅의 피 2개를 혈투의 전장에 있는 현자 리드로스에게 갖다 주고 신속의 영석을 받아야 합니다.",
    [7484] = "집중의 성서, 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 4개, 그리고 어둠의 허물 2개를 혈투의 전장에 있는 현자 리드로스에게 갖다 주고 집중의 영석을 받아야 합니다.",
    [7485] = "보호의 성서, 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 2개, 그리고 닳아해진 누더기골렘 조각 1개를 혈투의 전장에 있는 현자 리드로스에게 갖다 주고 보호의 영석을 받아야 합니다.",
    [7486] = "히드락시스의 궤짝에 든 보상을 차지하십시오.",
    [7488] = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어에게 레스텐드리스의 그물을 가져가야 합니다.",
    [7489] = "페랄라스의 모자케 야영지에 있는 탈로 쏜후프에게 레스텐드리스의 그물을 가져가야 합니다.",
    [7490] = "오그리마에 있는 대족장 스랄에게 오닉시아의 머리를 보여줘야 합니다.",
    [7491] = "힘의 골짜기에서 대군주 룬탁을 찾으십시오.",
