    [7506] = "주인에게 책을 되돌려주십시오.",
    [7507] = "노스트로의 용사냥 개론을 도서관에 되돌려주어야 합니다.",
    [7508] = "납작하고 무딘 엘프 검을 현자 리드로스에게 주어야 합니다.",
    [7509] = "오닉시아가 달궈지지 않은 고대의 검에 화염 숨결을 내뿜도록 한 후, 달궈진 고대의 검을 뽑으십시오. 달궈진 고대의 검은 언제까지나 달구어져 있지 않으니 서둘러야 합니다. 마지막 단계로 오닉시아의 시체에 달궈진 고대의 검을 꽂으십시오. 이렇게 하면 쿠엘세라 검을 가질 수 있습니다.",
    [7562] = "불타는 평원에 있는 모르줄 블러드브링어와 대화하십시오.",
    [7563] = "불타는 평원에 있는 모르줄 블러드브링어에게 흉포한 올빼미야수의 피 30병을 가져가야 합니다.",
    [7564] = "불타는 평원에 있는 고르지키 와일드아이즈에게 피가 담긴 상자를 가져가야 합니다.",
    [7581] = "페랄라스에 있는 혈투의 전장으로 간 다음 굽이나무 지구에 서식하는 야생혈족 사티르로부터 사티르의 피 15개를 회수한 후 타락의 흉터에 있는 다이오에게 돌아가야 합니다.",
    [7582] = "여명의 설원에 있는 검은속삭임 협곡에서 서식하는 헤더린의 악마들로부터 헤더린의 눈물 5개를 빼앗아야 합니다. 임무를 완수하면 타락의 흉터에 있는 다이오에게 돌아가십시오.",
    [7583] = "타락의 흉터에서 파멸의수호병을 찾아내십시오. 빛나는 수정 감옥을 파멸의수호병에게 사용해야 합니다. 악마는 잡히지 않으려고 맹렬하게 공격할 테니 정신을 바짝 차리십시오. 성공하면 사로잡은 파멸의수호병을 타락의 흉터에 있는 다이오에게 데려가야 합니다.",
    [7601] = "악령의 숲에 있는 임프시와 대화하십시오.",
    [7602] = "악령의 숲에 있는 임프시가 이 세계의 각기 다른 세 개의 지역에서 완전무결한 지옥의 정수 3개를 가져와 달라고 부탁했습니다. 아즈샤라에는 레가쉬 사티로스들, 자에데나르에는 자에데나르 부대원들, 그리고 저주받은 땅에서는 지옥군단병 보초들이 각기 그 지역의 완전무결한 지옥의 정수를 갖고 있습니다. 완전무결한 지옥의 정수 3개를 다 모은 다음에는 악령의 숲에 있는 임프시에게 돌아가야 합니다.",
    [7603] = "악령의 숲에 있는 불벼락 골짜기를 수색해 크로쉬우스의 잔해를 찾아야 합니다. 찾으면 부근에서 지옥의 불꽃을 사용해 크로쉬우스를 되살리십시오. 크로쉬우스가 깨어나면 놈을 쓰러뜨린 후 크로쉬우스의 지옥핵을 꺼내야 합니다. 크로쉬우스의 지옥핵을 악령의 숲에 있는 전지전능한 나이비에게 가져다주십시오.",
    [7604] = "설퍼론 도면을 받으려면 설퍼론 주괴와 토륨 대장조합 계약서를 로크토스 다크바게이너에게 가져가야 합니다.",
    [7622] = "15명이 살해 당하기 전에 인부 50명을 구해야 합니다. 이 임무를 완수하면 에리스 헤븐파이어와 대화하십시오. 살해 당한 농부의 수를 보려면 죽음의 말뚝을 보십시오.",
    [7623] = "불타는 평원에 있는 고르지키에게서 어둠의 물약을 구입해야 합니다. 이 물약을 사용하여 자에데나르로 가서 군주 베인할로우와 대화하십시오.",
    [7624] = "울라텍과 맞서 싸운 후 자에데나르에 있는 베인할로우 군주에게 배신자의 증거를 가져가야 합니다.",
    [7625] = "우르단에게서 소로시안 별가루를 구입한 후, 불타는 평원에 있는 고르지키 와일드아이즈에게 가져가야 합니다.",
    [7626] = "불타는 평원에 있는 고르지키 와일드아이즈에게 암흑 강화의 비약 10개를 가져가야 합니다.",
    [7627] = "불타는 평원에 있는 고르지키 와일드아이즈에게 눈부신 큰 결정 6개와 검은무쇠 광석 25개를 가져가야 합니다.",
    [7628] = "불타는 평원에 있는 고르지키 와일드아이즈에게 검은용 비늘 35개를 가져가야 합니다.",
    [7629] = "단지 안에 든 임프를 스칼로맨스에 있는 연금술 실험대로 가져가야 합니다. 양피지가 완성되면 단지를 고르지키 와일드아이즈에게 되돌려 주십시오.",
    [7630] = "불타는 평원에 있는 고르지키에게 아케이나이트 주괴 3개를 가져가야 합니다.",
    [7631] = "모르줄의 지시서를 잘 읽으십시오. 소로시안 공포마를 소환해 물리친 후 그 영혼을 결속시켜야 합니다.",
    [7632] = "단단한 고대의 잎사귀의 주인을 찾아야 합니다. 행운을 빕니다, <name>. 세상은 아주 넓으니까요.",
    [7634] = "고대정령 하스타트가 다 자란 푸른용 힘줄을 가져다 달라고 부탁했습니다. 이것을 찾으면 악령의 숲에 있는 하스타트에게 가져가십시오.",
    [7635] = "고대정령 스토마가 다 자란 검은용 힘줄을 가져다 달라고 부탁했습니다. 이것을 찾으면 악령의 숲에 있는 스토마에게 가져가십시오.",
    [7636] = "타락한 악령의 4인조를 찾아 처치해야 합니다. 매혹의 시몬 광기의 클린프랑 학살자 솔레노르 파멸의 인도자 아토리우스 위 넷의 혼을 갈무리하여 악령의 숲에 있는 고대정령 바르투스에게 돌아가십시오. 이들의 위치에 대한 단서는 바르투스가 주는 돌껍질을 참조하십시오. 이 임무는 반드시 혼자서 완수해야 합니다.",
    [7637] = "아이언포지에 가서 대사제 로한의 퇴마 향로를 가져와야 합니다. 퇴마 향로를 얻으려면 150골드를 기부해야 합니다.",
    [7638] = "스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경과 대화해야 합니다.",
    [7639] = "퇴마 향로를 가지고 스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다.",
    [7640] = "퇴마 향로를 사용하여 테러데일에 고통을 주는 영혼을 몰아내야 합니다. 25명의 테러데일 영혼을 해치운 다음 스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다.",
    [7641] = "스톰윈드의 드워프 지구에 있는 그리만트 엘모어와 대화해야 합니다.",
    [7642] = "룬무늬 옷감 40개, 아케이나이트 주괴 6개, 아서스의 눈물 10개, 스트라솔름 성수 물병 5개 그리고 150골드를 스톰윈드의 드워프 지구에 있는 그리만트 엘모어에게 가져가야 합니다.",
    [7643] = "사우스쇼어에 있는 메리데스 칼슨에게 말의 영혼에게 먹일 특별한 말 먹이를 얻어야 합니다. 페랄라스에 있는 혈투의 전장 던전으로 가서 굽이나무 텐드리스를 무찔러야 합니다. 굽이나무 텐드리스를 무찌르고 고대 준마의 영혼이 풀려나면 특별한 말 먹이를 먹여 영혼을 진정시키십시오. 마지막으로 아케이나이트 마갑을 주면 영혼이 축복을 내릴 것입니다.",
    [7644] = "축복받은 아케이나이트 마갑을 가지고 스톰윈드의 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다.",
    [7645] = "맛좋은 만나빵 20개를 모아서 힐스브래드 구릉지의 사우스쇼어에 있는 메리데스 칼슨에게 가져가야 합니다. 맛좋은 만나빵은 맛좋은 만나 사료에 꼭 필요한 재료입니다. 맛좋은 만나빵은 은빛 여명회에서 독점적으로 파는 것으로 알려져 있습니다. 메리데스 칼슨에게도 50골드를 주어야만 화가 난 마음을 진정시킬 수 있습니다.",
    [7646] = "스톰윈드의 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 아제로스 다이아몬드와 온전한 검은 다이아몬드를 가져가야 합니다.",
    [7647] = "스칼로맨스에 있는 대형 납골당 지하의 중심부로 가서 예언의 탐지기를 사용해야 합니다. 그러면 영혼들이 나타날 것이니 그들을 해치우십시오. 그들을 해치우면 죽음의 기사 다크리버가 나타날 것이니 그를 물리친 다음 군마의 영혼의 잃어버린 영혼을 되찾아야 합니다. 구원된 군마의 영혼과 축복받은 아케이나이트 마갑을 다크리버 군마의 영혼에게 돌려줘야 합니다.",
    [7648] = "스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 아케이나이트 마갑을 가져가야 합니다.",
    [7649] = "주인에게 책을 되돌려주십시오.",
    [7650] = "주인에게 책을 되돌려주십시오.",
    [7651] = "주인에게 책을 되돌려주십시오.",
    [7667] = "오그리마, 지혜의 골짜기에 있는 사고른 크레스트스트라이더의 일을 도우려면 그에게 아제로스 다이아몬드와 온전한 검은 다이아몬드를 가져가야 합니다.",
    [7670] = "스톰윈드의 대성당 광장에 있는 그레이슨 섀도브레이커 경과 대화해야 합니다.",
    [7701] = "이글거리는 협곡의 용광로에 있는 잿가루 채석장 깊은 곳에서 검은무쇠 드워프 변절자인 감독관 말토류스를 찾아 처치하고, 이글거리는 협곡에 있는 감시대장 롤로 롱스트라이커에게 그의 머리카락을 증거로 가져가 보상을 받아야 합니다.",
    [7703] = "권력의 고르독 건틀릿을 찾아 혈투의 전장에 있는 대장 크롬크러쉬에게 가져가야 합니다. 크롬크러쉬의 \"옛날 얘기\"에 따르면 자칭 왕자라는 토르텔드린이라는 이름의 \"기분 나쁜\" 엘프가 고르독 왕에게서 빼앗아갔다고 합니다.",
    [7721] = "페랄라스의 잊혀진 해안에 있는 바다 정령과 바다 물보라 정령에게서 물의 정령 핵 10개를 모아 부두 근처에 있는 조브린 팬대즐에게 가져가야 합니다.",
    [7722] = "용광로의 잿가루 채석장 어딘가에 감독관 말토류스가 훔친 비밀조제법: 불꽃 융해촉진제가 있을 것입니다. 이 조제법을 찾아서 이글거리는 협곡에 있는 수석대장장이 버니네이트에게 가져가야 합니다.",
    [7723] = "이글거리는 협곡의 용광로 주변을 돌아다니는 육중한 전투골렘 20마리를 처치하고 임무를 완수하면 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다.",
    [7724] = "이글거리는 협곡의 고원과 용암 웅덩이에 서식하는 불타는 용암거미 20마리를 찾아 처치해야 합니다. 불타는 용암거미를 충분히 처치한 후에는 이글거리는 협곡에 있는 한셀 헤비핸드에게 가야 합니다.",
    [7725] = "페랄라스에서 눈에 띄는 아무 거인에게나 조브린의 형상축소기를 사용해 좀 더 다루기 쉬운 형태로 변환하십시오. 페랄라스의 잊혀진 해안 부두에 있는 조브린 팬대즐에게 이 변형된 거인들에게서 얻을 수 있는 축소화 잔류물 10개를 가져가야 합니다.",
    [7726] = "페랄라스의 잊혀진 해안에 있는 바다 정령과 바다 물보라 정령에게서 물의 정령 핵 6개를 모아 부두 근처에 있는 조브린 팬대즐에게 가져가야 합니다.",
    [7727] = "용광로에 있는 잿가루 채석장 안의 용암 지대를 점령하고 있는 인센도사우루스 20마리를 처치한 후, 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다.",
    [7728] = "이글거리는 협곡에 있는 작업반장 스크랜지에게 가열로 바람구멍과 감시병의 망원경을 찾아 가져가야 합니다. 이 물건들에 대해 가지고 있는 유일한 정보는 다음과 같습니다. 검은무쇠 드워프들이 훔쳐간 것이 분명합니다. 가열로 바람구멍은 대장장이들이 사용하는 대장 도구입니다. 감시병의 망원경은 감시병들에게 값으로 따질 수 없을 만큼 중요한 감시 도구입니다.",
    [7729] = "검은무쇠 감독관 15명과 검은무쇠 노예상인 15명을 처치하고 임무를 완수한 후, 이글거리는 협곡에 있는 작업반장 스크랜지에게 돌아가야 합니다.",
    [7730] = "페랄라스의 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 주크애쉬 등껍질 20개를 가져가야 합니다.",
    [7731] = "고통의 구덩이에서 채찍쐐기를 물리치고 페랄라스의 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 분비선을 가져가야 합니다.",
    [7732] = "오그리마 골목길에 사는 질지빈 드럼로어에게 모자케 야영지 주크애쉬 보고서를 전달해야 합니다.",
    [7733] = "페랄라스의 페더문 요새에 있는 프랫 맥그루벤에게 무쇠설인 가죽 10개를 가져가야 합니다.",
    [7734] = "페랄라스의 모자케 야영지에 있는 장도르 스위프트스트라이더에게 무쇠설인 가죽 10개를 가져가야 합니다.",
    [7735] = "페랄라스의 페더문 요새에 있는 프랫 맥그루벤에게 온전한 설인 가죽을 가져가야 합니다.",
    [7738] = "페랄라스의 모자케 야영지에 있는 장도르 스위프트스트라이더에게 완전한 설인 가죽을 가져가야 합니다.",
    [7761] = "아주 멍청한 오크로군요. 지배의 보주를 사용하려면 드라키사스의 낙인을 찾아 드라키사스의 징표를 받아야 할 거 같습니다. 이 편지에 따르면 드라키사스 사령관이 낙인을 지키고 있다고 하니 조사해 보는 것이 좋겠습니다.",
    [7781] = "스톰윈드에 있는 대영주 볼바르 폴드라곤에게 네파리안의 머리를 가져가야 합니다.",
    [7782] = "스톰윈드에 있는 영웅의 계곡으로 가서 야전사령관 아프라샤비와 대화하십시오.",
    [7783] = "오그리마에 있는 스랄에게 네파리안의 머리을 가져가야 합니다.",
    [7784] = "오그리마에 있는 대군주 사울팽과 대화하십시오. 힘의 골짜기에서 당신을 기다리고 있습니다.",
    [7785] = "환생의 관을 조사한 후, 대영주 데미트리안에게 가져다주십시오.",
    [7786] = "바람추적자 썬더란을 감옥에서 해방시키려면 실리더스에 있는 대영주 데미트리안에게 바람추적자의 족쇄의 오른쪽 조각과 왼쪽 조각, 엘레멘티움 주괴 10개, 그리고 불의 군주의 정수를 가져가야 합니다.",
    [7787] = "잠들어 있는 바람의 성검을 대영주 데미트리안 앞에 내 놓아야 합니다.",
    [7810] = "가시덤불 골짜기에 원형투기장에 있는 땅딸보 존 미스릴과 대화하십시오.",
    [7815] = "무쇠턱바다거북 15마리를 처치하고 동부 내륙지의 레반터스크 마을에 있는 낚시꾼 카툼에게 돌아가야 합니다.",
    [7816] = "감메리타를 처치하고 카툼의 최고급 미끼를 되찾아 동부 내륙지의 레반터스크 마을에 있는 낚시꾼 카툼에게 돌아가야 합니다. 카툼이 감메리타는 해안에서 다른 거북들과 함께 있다고 얘기해 줬습니다.",
    [7828] = "긴발톱 은빛갈기늑대 15마리와 긴울음 은빛갈기늑대 15마리를 처치한 후 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 돌아가야 합니다. 마코르가 이 늑대들은 동부 내륙지의 황야에 숨어 있다고 얘기해 줬습니다.",
    [7829] = "포악한 올빼미야수 20마리를 처치한 후 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 돌아가야 합니다. 마코르가 포악한 올빼미야수는 동부 내륙지의 황야에 서식한다고 얘기해 줬습니다.",
    [7830] = "우두머리 뾰족부리그리핀 한 마리를 처치하고 그 우두머리 그리핀의 깃털을 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 가져가야 합니다. 마코르의 얘기로는 우두머리 뾰족부리그리핀은 주로 동부 내륙지의 황야에 서식하는 희귀종이라고 합니다.",
    [7839] = "동부 내륙지의 레반터스크 마을에 있는 대장장이 슬래그트리에게 슬래그트리의 잃어버린 연장을 찾아 되찾아줘야 합니다. 대장장이 슬래그트리의 말에 의하면 그 도구들은 동부 내륙지의 북동쪽 지역에 있는 썩은가지부족 신전들 중 하나에 있을 것이라고 얘기했으며 굼벵이 바위굴도 조사해 보는 것이 좋겠습니다.",
    [7840] = "동부 내륙지의 레반터스크 마을에 있는 라드에게 라드의 점심을 가져가야 합니다. 라드가 점심을 북쪽에 있는 섬에 두고왔다고 했습니다. 썩은가지부족 트롤을 조심하십시오.",
    [7841] = "깊은골짜기 길잡이 15명, 깊은골짜기 정찰대 15명, 깊은골짜기 명사수 15명, 그리고 깊은골짜기 순찰대 15명을 처치한 후 동부 내륙지의 레반터스크 마을에 있는 오토 모지코에게 돌아가야 합니다. 깊은골짜기 하이 엘프들은 동부 내륙지 북서쪽 지역에 있는 쿠엘다닐 오두막에 있습니다.",
    [7842] = "동부 내륙지의 레반터스크 마을에 있는 오토 모지코에게 동부 내륙지에 서식하는 그리핀을 처치하고 길고 고운 깃털 10개를 가져가야 합니다. 그리핀들은 동부 내륙지 전역에 서식하는 것으로 알려져 있습니다.",
    [7843] = "동부 내륙지 서쪽 지역에 있는 맹금의 봉우리로 가서 마을 중앙에 있는 우물 옆에 와일드해머일족에게 보내는 최후통첩장을 전달한 후, 레반터스크 마을에 있는 오토 모지코에게 돌아가야 합니다. 분노하는 와일드해머 드워프들과 난폭한 얼라이언스 일원들을 조심하십시오.",
    [7844] = "썩은가지부족 무두장이 30명과 썩은가지부족 예언자 15명을 처치하고 동부 내륙지의 레반터스크 마을에 있는 비술사 야요진에게 돌아가야 합니다. 야요진은 이 트롤들이 동부 내륙지의 북동부 지역에 있는 샤올와타 및 아골와타 신전 근처에 있다고 가르쳐 주었습니다.",
    [7845] = "동부 내륙지에 있는 레반터스크 마을의 주술사 쏜터스크가 그녀의 남편인 장로 쏜터스크를 진타알로에서 구해 달라고 부탁했습니다. 장로 쏜터스크는 동부 내륙지의 남쪽에 위치한 썩은가지부족의 수도인 진타알로의 꼭대기에 갇혀 있다고 합니다.",
    [7846] = "수호자 히타야를 죽이고 족쇄 열쇠를 찾아서 진타알로에 갇혀 있는 장로 쏜터스크에게 돌아가야 합니다.",
    [7847] = "장로 쏜터스크가 레반터스크 마을에 있는 주술사 쏜터스크에게 돌아가서 자신이 진타알로에서 풀려났다는 사실을 전해 달라고 부탁했습니다.",
    [7848] = "검은바위 나락의 화산 심장부 입구에 있는 차원의 문으로 가서 핵 조각을 하나 찾아야 합니다. 핵 조각을 가지고 검은바위 산에 있는 로소스 리프트웨이커에게로 돌아가십시오.",
    [7849] = "레반터스크 마을의 사냥꾼 마코르에게 쌍둥이 동생인 말코르의 해골을 찾아서 가져가야 합니다. 마코르가 말하기를 썩은가지부족의 수액괴물과 늑대들이 동생의 유골을 훼손하고 있다고 합니다. 또한 진타알로의 신전 근처에는 수액괴물이 가득한 쓰레기 폐허와 늑대 우리가 있다고 합니다.",
    [7850] = "진타알로에서 얼룩진 피가 담긴 용기 10개를 찾아 동부 내륙지에 있는 레반터스크 마을의 주술사 쏜터스크에게 돌아가야 합니다.",
    [7861] = "타락한 여사제 헥스와 썩은가지부족 아만자시 경비병 20명을 해치운 후, 동부 내륙지의 레반터스크 마을에 있는 주술사 쏜터스크와 대화해야 합니다. 동부 내륙지의 진타알로 꼭대기에 가면 타락한 여사제 헥스와 아만자시 경비병을 찾을 수 있습니다.",
    [7862] = "썩은가지부족 광전사 20명, 썩은가지부족 어둠사냥꾼 20명, 썩은가지부족 혈투사 20명, 썩은가지부족 영혼사냥꾼 20명을 처치한 후, 동부 내륙지의 레반터스크 마을에 있는 주술사 쏜터스크에게 돌아가야 합니다.",
    [7877] = "도서관으로 되돌아가 셴드랄라의 보물을 찾아야 합니다. 임무 완수에 대한 보상을 받으십시오!",
