    [8305] = "실리더스에서 눈물의 결정의 위치를 찾아 그 안을 응시하십시오.",
    [8306] = "실리더스의 세나리온 요새에 있는 지휘관 마랄리스가 여군주 나탈리아를 찾아 달라고 했습니다. 수집된 정보에 의하면 남쪽에 있는 하이브레갈에서 여군주 나탈리아 마랄리스를 찾을 수 있을 겁니다. 곤충 집에 들어가기 전에 브론즈비어드 야영지에 있는 드워프들을 찾아가야 합니다. 드워프들이 조언과 함께 다른 일을 줄 것입니다. 마지막으로 마랄리스가 했던 말 '그대가 해야 할 일을 하라.'를 기억해야 합니다.",
    [8307] = "세나리온 요새 서쪽에 있는 황혼의망치단 주둔지로 가서 미늘벌레 고기 조리법에 대한 정보를 알아내야 합니다.",
    [8308] = "실리더스 남쪽에 있는 브론즈비어드 야영지에 브란 브론즈비어드의 잃어버린 편지를 가져가야 합니다.",
    [8309] = "실리더스의 브론즈비어드 야영지에 루트거 글립쉐이퍼가 하이브아쉬, 하이브조라, 하이브레갈로 가서 각 곤충 집에 있는 문자가 새겨진 수정의 상형 문자 탁본을 구해 달라고 부탁했습니다. 지질학자의 탁본 도구를 사용하여 고대 상형 문자의 탁본을 만든 후 루트거 글립쉐이퍼에게 돌아가야 합니다.",
    [8310] = "실리더스의 브론즈비어드 야영지에 있는 프랭칼 스톤브리지가 하이브조라 실리시드 뇌, 하이브아쉬 실리시드 뇌, 하이브레갈 실리시드 뇌를 가져가야 합니다.",
    [8313] = "세나리온 요새 여관에 있는 캘랜드라스에게 찢어낸 조리법 페이지를 가져다 줘야 합니다.",
    [8314] = "브론즈비어드 야영지에 있는 루트거 글립쉐이퍼가 실리더스의 세나리온 요새에 있는 지질학자 락스베인에게 문자가 새겨진 수정 프리즘을 가져가 달라고 부탁했습니다.",
    [8315] = "실리더스의 세나리온 요새에 있는 지질학자 락스베인이 퀴라지 밀사에게서 수정 해독 장치를 되찾아 달라고 부탁했습니다. 세나리온 요새 남쪽에 있는 그락카론드의 무덤에 부름의 상형 문자를 가지고 간 후 사막에서 대군주를 소환해야 합니다. 퀴라지 밀사가 나타나면 밀사를 해치우고 수정 해독 장치를 회수한 후 지질학자 락스베인에게 돌아가야 합니다. 이 일을 완료하려면 군대를 소집해야 합니다!",
